   const resultMessage = document.getElementById('result-message');

   form.addEventListener('submit', (e) => {
     e.preventDefault();

     const q1Checked = document.querySelectorAll('input[name="q1"]:checked').length > 0;
     const q2Checked = document.querySelectorAll('input[name="q2"]:checked').length > 0;
     const q3Checked = document.querySelectorAll('input[name="q3"]:checked').length > 0;

     if (!q1Checked || !q2Checked || !q3Checked) {
       resultMessage.className = 'error';
       resultMessage.textContent = 'Error: Please select at least one answer for each question before submitting.';
       resultMessage.hidden = false;
       return;
     }

     const q1Values = Array.from(document.querySelectorAll('input[name="q1"]:checked')).map(cb => cb.value);
     const q2Values = Array.from(document.querySelectorAll('input[name="q2"]:checked')).map(cb => cb.value);
