     const correctAnswers = {
       q1: ['python', 'javascript'],
       q2: ['java', 'kotlin', 'scala'],
       q3: ['haskell', 'csharp', 'lisp']
     };

     let totalCorrect = 0;

     const q1Correct = q1Values.every(v => correctAnswers.q1.includes(v)) && 
                       q1Values.length === correctAnswers.q1.length;
     const q2Correct = q2Values.every(v => correctAnswers.q2.includes(v)) && 
                       q2Values.length === correctAnswers.q2.length;
     const q3Correct = q3Values.every(v => correctAnswers.q3.includes(v)) && 
                       q3Values.length === correctAnswers.q3.length;

     if (q1Correct) totalCorrect++;
     if (q2Correct) totalCorrect++;
     if (q3Correct) totalCorrect++;

     const score = totalCorrect;
     resultMessage.className = 'success';
     resultMessage.textContent = `Quiz submitted! You got ${score} out of 3 questions correct. ${
